function packFor(b) {
  if (b < 1500) return ['Kraft mailer with printed sleeve', 'Eco-friendly, light to ship pan-India.', 'kraft mailer'];
  if (b < 5000) return ['Rigid box with branded sleeve', 'Your colours on the sleeve, logo on the lid.', 'rigid box with sleeve'];
  if (b < 12000) return ['Magnetic rigid box, foil logo', 'Soft-touch finish with a foil-stamped logo.', 'magnetic box with foil logo'];
  return ['Premium leatherette box, debossed', 'Keepsake box with a debossed logo and satin lining.', 'premium keepsake box'];
}
function build(target, auds, occs, skip) {
  const fits = POOL.filter(p => (!auds.length && !occs.length) || auds.some(a => p.aud.includes(a)) || occs.some(o => p.occ.includes(o)));
  const src = fits.length ? fits : POOL;
  // Aim for 3 items around a third of the budget each, so kits feel curated rather than one big item.
  const aim = target / 3;
  const ranked = src.slice().sort((a, b) => Math.abs(a.deal - aim) - Math.abs(b.deal - aim));
  const pool = ranked.slice(skip).concat(ranked.slice(0, skip));
  let total = 0; const picked = []; const cats = {};
  for (const p of pool) { if (picked.length < 4 && !cats[p.cat] && total + p.deal <= target) { picked.push(p); cats[p.cat] = 1; total += p.deal; } }
  if (!picked.length) { const c = POOL[POOL.length - 1]; picked.push(c); total += c.deal; }
  return { picked, total };
}
function kbRgb(hex) { const h = String(hex || '#000000').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.substr(i, 2), 16) || 0); }
function kbDark(hex) { const [r, g, b] = kbRgb(hex); return (0.299 * r + 0.587 * g + 0.114 * b) / 255 < 0.6; }
function kbTint(hex, t) { const c = kbRgb(hex).map(v => Math.round(v + (255 - v) * t)); return '#' + c.map(v => v.toString(16).padStart(2, '0')).join(''); }
const pad2 = (n) => String(n).padStart(2, '0');
function todayStr() { const d = new Date(); return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }
function menuVals(self) { const m = !!self.state.menu; return { menuOpen: m, menuShut: !m, menuCls: m ? 'is-open' : '', menuLabel: m ? 'Close menu' : 'Open menu', toggleMenu: () => self.setState({ menu: !m }) }; }
function scrollToBrief() { try { const el = document.getElementById('brief'); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (e) {} }

class BespokePage extends DCLogic {
constructor(p) { super(p); this.state = { budget: 3000, qty: 250, date: '', auds: ['Dealers & channel'], occs: ['Dealer meets'], brands: ['Laser engraving'], bk: { name: '', phone: '', date: '', slot: '11:00 AM' }, bkErr: false, bkDone: false, notes: '', c1: '#1F3A5F', c2: '#C22B54', useBrand: false, step: 'A', f: { name: '', company: '', email: '', phone: '', city: '', call: 'Any time' }, err: false, done: false, ref: '' }; }
renderVals() {
  const s = this.state;
  const fmt = (n) => Math.round(n).toLocaleString('en-IN');
  const multi = (list, key) => list.map(l => { const on = s[key].includes(l); return { label: l, cls: on ? 'is-on' : '', pressed: on ? 'true' : 'false', pick: () => this.setState({ [key]: on ? s[key].filter(v => v !== l) : s[key].concat([l]) }) }; });
  const q = Math.max(0, Number(s.qty) || 0);
  const sug = PALETTES[s.occs[0]] || ['Kivart classic', [['#C22B54', 'Kivart pink'], ['#5E1029', 'Maroon'], ['#F6E6EB', 'Blush'], ['#1E1B1D', 'Charcoal']]];
  // Your own brand colours win over the occasion suggestion.
  const pal = s.useBrand ? ['Your brand colours', [[s.c1, 'Primary'], [s.c2, 'Secondary'], [kbTint(s.c1, 0.86), 'Light tint'], [kbDark(s.c1) ? '#FFFFFF' : '#1E1B1D', kbDark(s.c1) ? 'White' : 'Charcoal']]] : sug;
  const pk = packFor(s.budget);
  const tiers = [['UNDER BUDGET', 0.75, 'Smart Essentials', 4], ['ON BUDGET', 1.0, 'Signature Kit', 1], ['STRETCH', 1.3, 'Premium Edit', 0]];
  const kits = tiers.map(t => { const b = build(s.budget * t[1], s.auds, s.occs, t[3]); return { tier: t[0], title: t[2], items: b.picked.map(p => p.name + ' · ' + p.cat), imgs: b.picked.map(p => p.img), perFmt: fmt(b.total), orderFmt: fmt(b.total * q) }; });
  const onF = (k) => (e) => this.setState({ f: Object.assign({}, s.f, { [k]: e.target.value }), err: false });
  const dateTxt = s.date ? new Date(s.date + 'T00:00:00').toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '';
  const briefLine = fmt(q) + ' gifts at ₹' + fmt(s.budget) + ' each' + (s.useBrand ? ' · brand colours ' + s.c1.toUpperCase() + ' / ' + s.c2.toUpperCase() : '') + (s.auds.length ? ' for ' + s.auds.join(', ') : '') + (s.occs.length ? ' · ' + s.occs.join(', ') : '') + (dateTxt ? ' · needed by ' + dateTxt : '') + (s.brands.length ? ' · ' + s.brands.join(', ') : '');
  return {
    ...menuVals(this),
    notDone: !s.done, done: s.done, isA: s.step === 'A', isB: s.step === 'B',
    tabA: s.step === 'A' ? 'is-on' : '', tabB: s.step === 'B' ? 'is-on' : '', selA: s.step === 'A' ? 'true' : 'false', selB: s.step === 'B' ? 'true' : 'false',
    toA: () => this.setState({ step: 'A' }), toB: () => this.setState({ step: 'B' }),
    budget: s.budget, budgetFmt: '₹' + fmt(s.budget) + (s.budget >= 25000 ? '+' : ''), qty: s.qty, qtyFmt: fmt(q) + ' gifts', date: s.date, today: todayStr(), notes: s.notes,
    setBudget: (e) => this.setState({ budget: Number(e.target.value) }),
    setQty: (e) => this.setState({ qty: Number(e.target.value) }),
    setDate: (e) => this.setState({ date: e.target.value }),
    setNotes: (e) => this.setState({ notes: e.target.value }),
    auds: multi(AUDS, 'auds'), occs: multi(OCCS, 'occs'), brands: multi(BRANDING, 'brands'),
    f: s.f, on: { name: onF('name'), company: onF('company'), email: onF('email'), phone: onF('phone'), city: onF('city'), call: onF('call') },
    err: s.err, briefLine,
    submit: () => {
      const f = s.f; const ph = String(f.phone).replace(/\D/g, '').slice(-10);
      if (!f.name.trim() || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(f.email.trim()) || ph.length !== 10) { this.setState({ err: true }); return; }
      this.setState({ done: true, err: false, ref: 'KB-' + String(Date.now() % 100000).padStart(5, '0') }); scrollToBrief();
    },
    ref: s.ref, firstName: (s.f.name.trim().split(' ')[0] || 'there'),
    doneLine: 'We have your brief for ' + briefLine + '. Our team will email ' + (s.f.email || 'you') + ' a moodboard within 48 hours and call you on ' + (s.f.phone || 'your number') + ' (' + s.f.call.toLowerCase() + ') to walk you through it.',
    restart: () => this.setState({ done: false, step: 'A', ref: '' }),
    // moodboard
    summary: fmt(q) + ' gifts · ₹' + fmt(s.budget) + ' each' + (s.occs.length ? ' · ' + s.occs[0] + (s.occs.length > 1 ? ' +' + (s.occs.length - 1) : '') : ''),
    paletteName: pal[0].toUpperCase(), paletteHint: s.useBrand ? 'From the colours you picked' : 'Suggested for ' + (s.occs[0] || 'your occasion') + '. Add your brand colours to swap it.',
    logoInk: kbDark(pal[1][0][0]) ? '#FFFFFF' : '#1E1B1D',
    c1: s.c1, c2: s.c2, c1Up: String(s.c1).toUpperCase(), c2Up: String(s.c2).toUpperCase(), useBrand: s.useBrand,
    setC1: (e) => this.setState({ c1: e.target.value, useBrand: true }), setC2: (e) => this.setState({ c2: e.target.value, useBrand: true }),
    resetColours: () => this.setState({ useBrand: false }), palette: pal[1].map(([hex, name]) => ({ hex, name })),
    boxLid: pal[1][0][0], boxBase: pal[1][2][0], boxSleeve: pal[1][1][0],
    packName: pk[0], packNote: pk[1], packShort: pk[2],
    hasBrandChips: s.brands.length > 0, brandChips: s.brands,
    kits,
    work: WORK.map(([id, title, tag, v]) => ({ img: '/assets/' + id, title, tag, isVideo: v })),
    opts: OPTS.map(([title, desc, lead, icon]) => ({ title, desc, lead, icon })),
    boxes: BOXES.map(b => { const d = deal(b.mrp); return { name: b.name, img: b.img, feats: b.feats, mrpFmt: fmt(b.mrp), dealFmt: fmt(d), use: () => { this.setState({ budget: Math.min(25000, Math.max(500, Math.round(d / 500) * 500)), notes: 'Start from the ' + b.name + ' kit (' + b.feats.slice(0, 3).join(', ') + ') and customise it.', step: 'A', done: false }); scrollToBrief(); } }; }),
    bk: s.bk, bkOpen: !s.bkDone, bkDone: s.bkDone, bkErr: s.bkErr,
    onBk: { name: (e) => this.setState({ bk: Object.assign({}, s.bk, { name: e.target.value }), bkErr: false }), phone: (e) => this.setState({ bk: Object.assign({}, s.bk, { phone: e.target.value }), bkErr: false }), date: (e) => this.setState({ bk: Object.assign({}, s.bk, { date: e.target.value }), bkErr: false }) },
    slots: ['11:00 AM', '1:00 PM', '3:00 PM', '5:00 PM'].map(l => { const on = s.bk.slot === l; return { label: l, cls: on ? 'is-on' : '', pressed: on ? 'true' : 'false', pick: () => this.setState({ bk: Object.assign({}, s.bk, { slot: l }) }) }; }),
    submitBk: () => { const ph = String(s.bk.phone).replace(/\D/g, '').slice(-10); if (!s.bk.name.trim() || ph.length !== 10 || !s.bk.date) { this.setState({ bkErr: true }); return; } this.setState({ bkDone: true, bkErr: false }); },
    bkSummary: (s.bk.name || 'You') + ' · ' + (s.bk.date ? new Date(s.bk.date + 'T00:00:00').toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' }) : '') + ', ' + s.bk.slot,
    bkReset: () => this.setState({ bkDone: false, bk: { name: '', phone: '', date: '', slot: '11:00 AM' } }),
    toVisit: (e) => { try { e.preventDefault(); const el = document.getElementById('visit'); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch (x) {} },
    toBrief: (e) => { try { e.preventDefault(); } catch (x) {} scrollToBrief(); }
  };
}
}

